// SetCourse of the fileinfo to the related item.
// Sets o.R.Course to related.
// Adds o to related.R.Fileinfos.
func (o *Fileinfo) SetCourse(exec boil.Executor, insert bool, related *Course) error {
	var err error
	if insert {
		if err = related.Insert(exec, boil.Infer()); err != nil {
			return errors.Wrap(err, "failed to insert into foreign table")
		}
	}

	updateQuery := fmt.Sprintf(
		"UPDATE \"fileinfo\" SET %s WHERE %s",
		strmangle.SetParamNames("\"", "\"", 1, []string{"course_id"}),
		strmangle.WhereClause("\"", "\"", 2, fileinfoPrimaryKeyColumns),
	)
	values := []any{related.ID, o.ID}

	if boil.DebugMode {
		fmt.Fprintln(boil.DebugWriter, updateQuery)
		fmt.Fprintln(boil.DebugWriter, values)
	}
	if _, err = exec.Exec(updateQuery, values...); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	queries.Assign(&o.CourseID, related.ID)
	if o.R == nil {
		o.R = &fileinfoR{
			Course: related,
		}
	} else {
		o.R.Course = related
	}

	if related.R == nil {
		related.R = &courseR{
			Fileinfos: FileinfoSlice{o},
		}
	} else {
		related.R.Fileinfos = append(related.R.Fileinfos, o)
	}

	return nil
}

// RemoveCourse relationship.
// Sets o.R.Course to nil.
// Removes o from all passed in related items' relationships struct.
func (o *Fileinfo) RemoveCourse(exec boil.Executor, related *Course) error {
	var err error

	queries.SetScanner(&o.CourseID, nil)
	if _, err = o.Update(exec, boil.Whitelist("course_id")); err != nil {
		return errors.Wrap(err, "failed to update local table")
	}

	if o.R != nil {
		o.R.Course = nil
	}
	if related == nil || related.R == nil {
		return nil
	}

	for i, ri := range related.R.Fileinfos {
		if queries.Equal(o.CourseID, ri.CourseID) {
			continue
		}

		ln := len(related.R.Fileinfos)
		if ln > 1 && i < ln-1 {
			related.R.Fileinfos[i] = related.R.Fileinfos[ln-1]
		}
		related.R.Fileinfos = related.R.Fileinfos[:ln-1]
		break
	}
	return nil
}

